template<int N>
struct Factorial {
    static const int value = N * Factorial<N - 1>::value;
};

template<>
struct Factorial<0> {
    static const int value = 1;
};

// Result is computed at compile time
// int result = Factorial<5>::value;

constexpr unsigned long long factorial_ct(int n) {
    return (n <= 1) ? 1 : (n * factorial_ct(n - 1));
}

constexpr unsigned long long FIVE_FACT = factorial_ct(5);


